@app.route('/api/search', methods=['POST'])
def api_search():
    """Genspark 검색 API"""
    try:
        data = request.json
        query = data.get('query', '').strip()

        if not query:
            return jsonify({'success': False, 'error': '검색어를 입력하세요.'}), 400

        # GensparkAgent 실행
        api_key = os.environ.get('ANTHROPIC_API_KEY')
        if not api_key:
            return jsonify({
                'success': False,
                'error': 'ANTHROPIC_API_KEY 환경변수가 설정되지 않았습니다.'
            }), 500

        config = AgentConfig(
            anthropic_api_key=api_key,
            max_search_results=data.get('max_results', 5),
            output_dir='output',
            verbose=False
        )

        agent = GensparkAgent(config)
        result = agent.run(query)

        if result:
            # 파일명 추출
            filename_html = result.html_path.split('/')[-1]
            filename_md = result.markdown_path.split('/')[-1]

            return jsonify({
                'success': True,
                'data': {
                    'query': query,
                    'confidence_score': 0.85,  # 실제로는 result에서 가져옴
                    'total_sources': 5,
                    'sections': 4,
                    'generated_at': datetime.now().strftime('%Y-%m-%d %H:%M'),
                    'filename_html': filename_html,
                    'filename_md': filename_md,
                }
            })
        else:
            return jsonify({
                'success': False,
                'error': 'Sparkpage 생성에 실패했습니다.'
            }), 500

    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@app.route('/download/<filename>')
def download_file(filename):
    """파일 다운로드"""
    try:
        file_path = os.path.join('output', filename)
        if os.path.exists(file_path):
            return send_file(file_path, as_attachment=True)
        else:
            return '파일을 찾을 수 없습니다.', 404
    except Exception as e:
        return str(e), 500

@app.route('/view/<filename>')
def view_file(filename):
    """파일 미리보기"""
    try:
        file_path = os.path.join('output', filename)
        if os.path.exists(file_path):
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            return content
        else:
            return '파일을 찾을 수 없습니다.', 404
    except Exception as e:
        return str(e), 500

